#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // For quick edge existence check
    vector<unordered_set<int>> adj_set(n+1);
    for(int u=1;u<=n;u++){
        adj_set[u] = unordered_set<int>(adj[u].begin(), adj[u].end());
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count(); };

    mt19937 rng(42);

    vector<int> best_path;

    while(elapsed_ms() < 3500){
        int sv = rng() % n + 1;

        // Use deque for efficient front/back extension
        deque<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv);
        used[sv] = true;

        // Extend back greedily
        auto try_extend_back = [&]() -> bool {
            int cur = path.back();
            // Shuffle neighbors and pick one with smallest out-degree among unused (Warnsdorff)
            auto& nb = adj[cur];
            int best = -1, best_sc = INT_MAX;
            for(int v : nb){
                if(used[v]) continue;
                int sc = 0;
                for(int w : adj[v]) if(!used[w]) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            path.push_back(best);
            return true;
        };

        auto try_extend_front = [&]() -> bool {
            int cur = path.front();
            auto& nb = radj[cur];
            int best = -1, best_sc = INT_MAX;
            for(int v : nb){
                if(used[v]) continue;
                int sc = 0;
                for(int w : radj[v]) if(!used[w]) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            used[best] = true;
            path.push_front(best);
            return true;
        };

        while(try_extend_back());
        while(try_extend_front());

        // Repeated: try rotation then extend
        for(int rot = 0; rot < 500 && (int)path.size() < n; rot++){
            int tail = path.back();
            vector<int> cands;
            for(int v : adj[tail]){
                if(!used[v]) continue;
                // find position - skip, just try: if tail->v and v is in path, truncate after v and re-extend
            }
            // Truncate from back randomly and re-extend
            int cut = rng() % max(1, (int)path.size() / 4) + 1;
            for(int i = 0; i < cut && path.size() > 1; i++){
                used[path.back()] = false;
                path.pop_back();
            }
            while(try_extend_back());
            while(try_extend_front());
        }

        if((int)path.size() > (int)best_path.size()){
            best_path.assign(path.begin(), path.end());
            if((int)best_path.size() == n) break;
        }
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
}
